const NAME_RE = /^[A-Za-z0-9_-]+/
const DIGITS = String.raw`\d+(?:_\d+)*`
const INT_RE = new RegExp(`^[+-]?${DIGITS}$`)
const FRAC = String.raw`\.${DIGITS}`
const EXP = String.raw`[eE][+-]?${DIGITS}`
const FLOAT_RE = new RegExp(`^[+-]?${DIGITS}(?:${FRAC}(?:${EXP})?|${EXP})$`)

function newTable(path) {
  return { type: 'table', map: new Map(), headered: false, path }
}

class LineScanner {
  constructor(line, lineNo, fail) {
    this.s = line
    this.n = line.length
    this.i = 0
    this.lineNo = lineNo
    this.fail = fail
  }

  atEnd() {
    return this.i >= this.n
  }

  skipWSAndComment() {
    const { s } = this
    while (this.i < this.n && (s[this.i] === ' ' || s[this.i] === '\t')) this.i++
    if (this.i < this.n && (s[this.i] === '#' || s[this.i] === ';')) this.i = this.n
  }

  parseBasicString() {
    const { s } = this
    this.i++ // consume opening quote
    let out = ''
    for (;;) {
      if (this.i >= this.n) this.fail('unterminated string')
      const c = s[this.i]
      if (c === '"') {
        this.i++
        return out
      }
      if (c === '\\') {
        this.i++
        if (this.i >= this.n) this.fail('unterminated string')
        const e = s[this.i]
        switch (e) {
          case '"':
            out += '"'
            this.i++
            break
          case '\\':
            out += '\\'
            this.i++
            break
          case 'n':
            out += '\n'
            this.i++
            break
          case 't':
            out += '\t'
            this.i++
            break
          case 'r':
            out += '\r'
            this.i++
            break
          case '0':
            out += '\0'
            this.i++
            break
          case 'u': {
            this.i++
            const hex = s.slice(this.i, this.i + 4)
            if (hex.length < 4 || !/^[0-9a-fA-F]{4}$/.test(hex)) this.fail('invalid escape \\u')
            out += String.fromCharCode(parseInt(hex, 16))
            this.i += 4
            break
          }
          default:
            this.fail(`invalid escape \\${e}`)
        }
      } else {
        out += c
        this.i++
      }
    }
  }

  parseLiteralString() {
    const { s } = this
    this.i++ // consume opening quote
    let out = ''
    for (;;) {
      if (this.i >= this.n) this.fail('unterminated string')
      const c = s[this.i]
      if (c === "'") {
        this.i++
        return out
      }
      out += c
      this.i++
    }
  }

  parseName() {
    this.skipWSAndComment()
    if (this.i >= this.n) this.fail('expected a name')
    const c = this.s[this.i]
    if (c === '"') return this.parseBasicString()
    if (c === "'") return this.parseLiteralString()
    const m = NAME_RE.exec(this.s.slice(this.i))
    if (!m) this.fail('expected a name')
    this.i += m[0].length
    return m[0]
  }

  parseDottedName() {
    const names = [this.parseName()]
    for (;;) {
      const save = this.i
      this.skipWSAndComment()
      if (this.i < this.n && this.s[this.i] === '.') {
        this.i++
        names.push(this.parseName())
      } else {
        this.i = save
        break
      }
    }
    return names
  }

  resolveAssignTarget(tableNode, names) {
    let cur = tableNode
    let curPath = tableNode.path
    for (let idx = 0; idx < names.length - 1; idx++) {
      const name = names[idx]
      const childPath = curPath === '' ? name : `${curPath}.${name}`
      if (cur.map.has(name)) {
        const ex = cur.map.get(name)
        if (ex.type === 'table') {
          cur = ex
        } else if (ex.type === 'atable') {
          cur = ex.items[ex.items.length - 1]
        } else {
          this.fail(`${childPath} is not a table`)
        }
      } else {
        const nt = newTable(childPath)
        cur.map.set(name, nt)
        cur = nt
      }
      curPath = childPath
    }
    const finalName = names[names.length - 1]
    const finalPath = curPath === '' ? finalName : `${curPath}.${finalName}`
    if (cur.map.has(finalName)) this.fail(`key ${finalPath} is defined twice`)
    return { cur, finalName, finalPath }
  }

  readValue(prefixPath) {
    this.skipWSAndComment()
    if (this.i >= this.n) this.fail('expected a value')
    const c = this.s[this.i]
    if (c === '"') return { type: 'string', value: this.parseBasicString() }
    if (c === "'") return { type: 'string', value: this.parseLiteralString() }
    if (c === '[') return this.parseArrayValue(prefixPath)
    if (c === '{') return this.parseInlineTableValue(prefixPath)
    return this.parseUnquotedValue()
  }

  parseUnquotedValue() {
    const { s } = this
    const start = this.i
    while (this.i < this.n && s[this.i] !== ' ' && s[this.i] !== '\t' && s[this.i] !== ',' && s[this.i] !== ']' && s[this.i] !== '}') {
