    const items = []
    this.skipWSAndComment()
    if (this.i >= this.n) this.fail('unterminated array')
    if (this.s[this.i] === ']') {
      this.i++
      return { type: 'array', items }
    }
    for (;;) {
      items.push(this.readValue(prefixPath))
      this.skipWSAndComment()
      if (this.i >= this.n) this.fail('unterminated array')
      if (this.s[this.i] === ',') {
        this.i++
        this.skipWSAndComment()
        if (this.i >= this.n) this.fail('unterminated array')
        if (this.s[this.i] === ']') {
          this.i++
          break
        }
        continue
      } else if (this.s[this.i] === ']') {
        this.i++
        break
      } else {
        this.fail('unterminated array')
      }
    }
    return { type: 'array', items }
  }

  parseInlineTableValue(prefixPath) {
    this.i++ // consume '{'
    const map = new Map()
    const localNode = { type: 'table', map, headered: false, path: prefixPath }
    this.skipWSAndComment()
    if (this.i >= this.n) this.fail('unterminated inline table')
    if (this.s[this.i] === '}') {
      this.i++
      return { type: 'table', map }
    }
    for (;;) {
      const names = this.parseDottedName()
      this.skipWSAndComment()
      if (this.i >= this.n || this.s[this.i] !== '=') this.fail('expected = in an inline table')
      this.i++
      const { cur, finalName, finalPath } = this.resolveAssignTarget(localNode, names)
      const val = this.readValue(finalPath)
      cur.map.set(finalName, val)
      this.skipWSAndComment()
      if (this.i >= this.n) this.fail('unterminated inline table')
      if (this.s[this.i] === ',') {
        this.i++
        this.skipWSAndComment()
        if (this.i >= this.n) this.fail('unterminated inline table')
        continue
      } else if (this.s[this.i] === '}') {
        this.i++
        break
      } else {
        this.fail('unterminated inline table')
      }
    }
    return { type: 'table', map }
  }
}

export class Parser {
  constructor() {
    this.root = newTable('')
    this.currentTable = this.root
  }

  fail(reason) {
    throw new ParseError(this.lineNo, reason)
  }

  parseDocument(text) {
    let lines = text.split('\n')
    if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()
    for (let idx = 0; idx < lines.length; idx++) {
      this.lineNo = idx + 1
      this.processLine(lines[idx])
    }
    return this.root
  }

  processLine(line) {
    let j = 0
    while (j < line.length && (line[j] === ' ' || line[j] === '\t')) j++
    if (j >= line.length) return
    if (line[j] === '#' || line[j] === ';') return

    const boundFail = (reason) => this.fail(reason)
    const scanner = new LineScanner(line, this.lineNo, boundFail)
    scanner.i = j

    if (scanner.s[scanner.i] === '[') {
      this.parseHeaderLine(scanner)
    } else {
      this.parseKeyValueLine(scanner)
    }
  }

  parseHeaderLine(scanner) {
    scanner.i++ // consume '['
    let isArray = false
    if (scanner.i < scanner.n && scanner.s[scanner.i] === '[') {
      isArray = true
      scanner.i++
    }
    const names = scanner.parseDottedName()
    scanner.skipWSAndComment()
    if (scanner.i >= scanner.n || scanner.s[scanner.i] !== ']') this.fail('unterminated table header')
    scanner.i++
    if (isArray) {
      if (scanner.i >= scanner.n || scanner.s[scanner.i] !== ']') this.fail('unterminated table header')
      scanner.i++
    }
    scanner.skipWSAndComment()
    if (scanner.i < scanner.n) this.fail('trailing text after a table header')
    this.applyHeader(names, isArray)
  }

  applyHeader(names, isArray) {
    let cur = this.root
    let curPath = ''
    for (let idx = 0; idx < names.length - 1; idx++) {
      const name = names[idx]
      const childPath = curPath === '' ? name : `${curPath}.${name}`
      if (cur.map.has(name)) {
        const ex = cur.map.get(name)
        if (ex.type === 'table') {
          cur = ex
        } else if (ex.type === 'atable') {
          cur = ex.items[ex.items.length - 1]
        } else {
          this.fail(`${childPath} is not a table`)
        }
      } else {
        const nt = newTable(childPath)
        cur.map.set(name, nt)
        cur = nt
      }
      curPath = childPath
    }
    const finalName = names[names.length - 1]
    const finalPath = curPath === '' ? finalName : `${curPath}.${finalName}`

    if (!isArray) {
      if (cur.map.has(finalName)) {
        const ex = cur.map.get(finalName)
        if (ex.type !== 'table') this.fail(`${finalPath} is not a table`)
        if (ex.headered) this.fail(`table ${finalPath} is defined twice`)
        ex.headered = true
        this.currentTable = ex
      } else {
        const nt = newTable(finalPath)
        nt.headered = true
        cur.map.set(finalName, nt)
        this.currentTable = nt
      }
    } else {
      if (cur.map.has(finalName)) {
        const ex = cur.map.get(finalName)
        if (ex.type !== 'atable') this.fail(`${finalPath} is not an array of tables`)
        const nt = newTable(finalPath)
        ex.items.push(nt)
        this.currentTable = nt
      } else {
        const nt = newTable(finalPath)
        const at = { type: 'atable', items: [nt] }
        cur.map.set(finalName, at)
        this.currentTable = nt
      }
    }
  }

  parseKeyValueLine(scanner) {
    const names = scanner.parseDottedName()
    scanner.skipWSAndComment()
    if (scanner.i >= scanner.n || scanner.s[scanner.i] !== '=') this.fail('expected key = value')
    scanner.i++
    const { cur, finalName, finalPath } = scanner.resolveAssignTarget(this.currentTable, names)
    const val = scanner.readValue(finalPath)
    scanner.skipWSAndComment()
    if (scanner.i < scanner.n) this.fail('trailing text after a value')
    cur.map.set(finalName, val)
  }
}

export function parseDocument(text) {
  return new Parser().parseDocument(text)
}
