      if (cur.map.has(finalName)) {
        const ex = cur.map.get(finalName)
        if (ex.type !== 'atable') this.fail(`${finalPath} is not an array of tables`)
        const nt = newTable(finalPath)
        ex.items.push(nt)
        this.currentTable = nt
      } else {
        const nt = newTable(finalPath)
